---InitValue 初始化数据
function GachaCoinQuestEntry:InitValue()
    local gachaCoinQuestDojo = GCQUtils.GetHomeDojo()

    ---@type integer @ 抽卡道具副本当前等级
    self.gachaCoinLevel = checkInt(gachaCoinQuestDojo.copyLevel)

    ---@type integer @ 当前获得的抽卡道具数量
    self.gachaCoinAmount = checkInt(gachaCoinQuestDojo.goodsSum)

    ---@type integer @ 抽卡道具副本当前倒计时
    self.gachaCoinCd = checkInt(gachaCoinQuestDojo.timeLeft)

    ---@type integer @ 抽卡道具副本获得的奖励id
    self.gachaCoinGoodsId = GCQConstants.Defines.GachaCoinGoodsId

    local titleInfoScript = GetLuaBehaviour(self.TitleInfo.gameObject, GCQConstants.Path.TitleInfoScript)
    if not IsNull(titleInfoScript) and not IsNull(titleInfoScript.Env) then
        ---@type GachaCoinQuestTitleInfo @ 标题板的脚本
        self.TitleInfoScript = titleInfoScript.Env
    end
end

---InitView 初始化界面
function GachaCoinQuestEntry:InitView()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id11)
    KTool.SetActive(self.EnterButton, isUnlock)
    KTool.SetActive(self.TimerInfo, isUnlock)
    KTool.SetActive(self.Lock, not isUnlock)
    if isUnlock then
        SetButtonAction(self.EnterButton, Bind(self, self.EntryButtonClickHandler))
    else
        local desc = GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id11)
        CfUtils.FillText(self.TxtLockTip, desc)
        SetButtonAction(self.Lock, function()
            GameUtils.Toast(desc)
        end)
    end

    --[[
    -- 进入副本按钮
    SetButtonAction(self.EnterButton, Bind(self, self.EntryButtonClickHandler))
    ]]
    
    -- 刷新一些状态

    self.TitleInfoScript:RefreshTitleInfo(
        self.gachaCoinLevel, self.gachaCoinAmount, self.gachaCoinGoodsId
    )
    self.TitleInfoScript:RefreshCountdown(self.gachaCoinCd)
end


